import{_ as e,o as i,c as n,a0 as t}from"./chunks/framework.DhQjJcnt.js";const p=JSON.parse('{"title":"Skill: /db-erd","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/db-erd.md","filePath":"references/skills/db-erd.md"}'),c={name:"references/skills/db-erd.md"};function l(o,a,r,h,s,d){return i(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="skill-db-erd" tabindex="-1">Skill: <code>/db-erd</code> <a class="header-anchor" href="#skill-db-erd" aria-label="Permalink to &quot;Skill: `/db-erd`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>db-erd</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/db-erd</code></li><li>Có thể kết hợp cờ khảo cổ mã nguồn cũ: <code>/legacy /db-erd</code></li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc các yêu cầu về nghiệp vụ để suy xuất ra các thực thể (Business Entities).</li><li>Nếu có <code>/legacy</code>: Khảo cổ file <code>legacy-repos.local.json</code> để mò lại database schema cũ (ví dụ: các file export SQL hoặc ORM models) rồi map sang mô hình nghiệp vụ mới.</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Sinh ra file tài liệu Markdown chứa sơ đồ thực thể liên kết (Entity-Relationship Diagram) viết bằng cú pháp Mermaid <code>erDiagram</code>.</li><li>Vị trí lưu file: Nằm ở cấp bậc dùng chung thấp nhất có thể (Lowest Common Ancestor - LCA) dạng <code>&lt;LCA&gt;/common/db-erd.md</code>.</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Kỹ năng thiết kế <strong>Cơ sở dữ liệu và Thực thể (Database ERD)</strong>.</li><li>Tập trung vào việc mô hình hóa các thực thể chia sẻ (Shared Entities), quyền sở hữu dữ liệu (Data Ownership) và tính bản số (Cardinality, vd: 1-n, n-n).</li><li>Tránh việc dump nguyên xi cấu trúc Database vật lý (Raw schema dump) hoặc ORM export vào file này, trừ khi ranh giới Repo hoàn toàn trùng khớp với ranh giới nghiệp vụ (rất hiếm). Thiết kế ERD phải dựa trên lăng kính nghiệp vụ (Business Lens).</li><li><strong>Lưu ý về mức độ chi tiết:</strong> Tại tầng Kiến trúc này, ERD mang tính chất Global (toàn cục), chỉ tập trung làm rõ mối quan hệ và các trường dữ liệu chính (Main fields). Các trường dữ liệu chi tiết li ti, hoặc các trường xử lý kỹ thuật ngầm (Derived data) sẽ được định nghĩa sâu hơn ở tầng Feature (Spec) hoặc tầng API Contract.</li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Nằm trong nhóm Kiến trúc (Architecture), thường được gọi sau khi đã hạch toán xong các <code>/surfaces</code> và <code>/module</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/db-erd</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const m=e(c,[["render",l]]);export{p as __pageData,m as default};
